"Поздравляю! Ты узнал много нового о живой природе, веществах, Земле и физике. Закрепляй знания в играх и проводи опыты!": "Құттықтаймын! Сен тірі табиғат, заттар, Жер және физика туралы көп жаңа нәрсе білдің. Білімді ойындарда бекіт, тәжірибе жаса!",
