"алмаз": "гауһар",
"артерия": "артерия",
"атмосферные воды": "атмосфералық сулар",
"баллон у водолаза": "сүңгуірдегі баллон",
"без опыта": "тәжірибесіз",
"без раздумий": "ойланбай",
"без участия человека": "адамның қатысынсыз",
